// Steamy tonkotsu ramen — make.fun food-picture-01 entry.
// The picture (JPEG bytes, base64) is embedded below and written to /output/entry.png.
// Run locally: mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const IMAGE_B64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
mkdirSync(outDir, { recursive: true });
const image = Buffer.from(IMAGE_B64, 'base64');
if (image.length === 0) throw new Error('Embedded image is empty');
writeFileSync(join(outDir, 'entry.png'), image);
